    if (num_val == -99) return(-3) 
    if (num_val == -92) return(-9) 
    if (num_val == -91) return(-1) 
    if (num_val == -1) return(-8)  
  } else if (wave == 'W5') {
    if (num_val == -1) return(-8)  
  } else if (wave == 'W6') {
    if (num_val == -92) return(-9) 
    if (num_val == -91) return(-1) 
